class MovieRentingSystem {
    private java.util.Map<Integer, java.util.TreeSet<int[]>> unrented = new java.util.HashMap<>();
    private java.util.TreeSet<int[]> rented = new java.util.TreeSet<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]);
    private java.util.Map<Long, Integer> price = new java.util.HashMap<>();
    public MovieRentingSystem(int n, int[][] entries) {
        for (int[] e : entries) {
            price.put((long) e[0] * 100001 + e[1], e[2]);
            unrented.computeIfAbsent(e[1], k -> new java.util.TreeSet<>((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]));
            unrented.get(e[1]).add(new int[]{e[2], e[0]});
        }
    }
    public java.util.List<Integer> search(int movie) {
        java.util.List<Integer> res = new java.util.ArrayList<>();
        if (!unrented.containsKey(movie)) return res;
        int cnt = 0;
        for (int[] entry : unrented.get(movie)) {
            res.add(entry[1]); if (++cnt == 5) break;
        }
        return res;
    }
    public void rent(int shop, int movie) {
        int p = price.get((long) shop * 100001 + movie);
        unrented.get(movie).remove(new int[]{p, shop});
        rented.add(new int[]{p, shop, movie});
    }
    public void drop(int shop, int movie) {
        int p = price.get((long) shop * 100001 + movie);
        rented.remove(new int[]{p, shop, movie});
        unrented.get(movie).add(new int[]{p, shop});
    }
    public java.util.List<java.util.List<Integer>> report() {
        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
        int cnt = 0;
        for (int[] entry : rented) {
            res.add(java.util.Arrays.asList(entry[1], entry[2]));
            if (++cnt == 5) break;
        }
        return res;
    }
}

import java.util.*;

class MovieRentingSystem {
    private Map<Long, Integer> priceMap;
    private Set<Long> rentedSet;
    private Map<Integer, List<long[]>> movieShops;
    public MovieRentingSystem(int n, int[][] entries) {
        priceMap = new HashMap();
        rentedSet = new HashSet();
        movieShops = new HashMap();
        for (int[] e : entries) {
            long key = (long) e[0] * 100001 + e[1];
            priceMap.put(key, e[2]);
            if (!movieShops.containsKey(e[1])) movieShops.put(e[1], new ArrayList());
            movieShops.get(e[1]).add(new long[]{e[2], e[0], e[1]});
        }
    }
    public List<Integer> search(int movie) {
        List<Integer> result = new ArrayList();
        if (!movieShops.containsKey(movie)) return result;
        List<long[]> shops = movieShops.get(movie);
        List<long[]> available = new ArrayList();
        for (int i = 0; i < shops.size(); i++) {
            long[] s = shops.get(i);
            long key = s[1] * 100001 + s[2];
            if (!rentedSet.contains(key)) available.add(s);
        }
        Collections.sort(available, new Comparator<long[]>() {
            public int compare(long[] a, long[] b) {
                if (a[0] != b[0]) return Long.compare(a[0], b[0]);
                return Long.compare(a[1], b[1]);
            }
        });
        for (int i = 0; i < Math.min(5, available.size()); i++) {
            result.add((int) available.get(i)[1]);
        }
        return result;
    }
    public void rent(int shop, int movie) {
        rentedSet.add((long) shop * 100001 + movie);
    }
    public void drop(int shop, int movie) {
        rentedSet.remove((long) shop * 100001 + movie);
    }
    public List<List<Integer>> report() {
        List<List<Integer>> result = new ArrayList();
        List<long[]> rented = new ArrayList();
        for (Long key : rentedSet) {
            int shop = (int)(key / 100001);
            int movie = (int)(key % 100001);
            int price = priceMap.get(key).intValue();
            rented.add(new long[]{price, shop, movie});
        }
        Collections.sort(rented, new Comparator<long[]>() {
            public int compare(long[] a, long[] b) {
                if (a[0] != b[0]) return Long.compare(a[0], b[0]);
                if (a[1] != b[1]) return Long.compare(a[1], b[1]);
                return Long.compare(a[2], b[2]);
            }
        });
        for (int i = 0; i < Math.min(5, rented.size()); i++) {
            List<Integer> pair = new ArrayList();
            pair.add((int) rented.get(i)[1]);
            pair.add((int) rented.get(i)[2]);
            result.add(pair);
        }
        return result;
    }
}
